#include "behavior_planner/decision/behavior_scorer.hpp"
namespace behavior_planner { BehaviorScore BehaviorScorer::score(const UrbanFeature&f,const HardConstraint&h)const{BehaviorScore s;s.keep=70;s.follow=f.surrounding.has_front_vehicle?65:-1e6;if(f.surrounding.has_front_vehicle){double t=f.surrounding.front_vehicle.ttc;s.keep-=t<3?35:10;s.follow+=t<3?20:5;}/* Temporary FOLLOW-only verification gate: keep lane-change candidates below every selectable maneuver until its FSM transitions are implemented. */s.left_change=-1e6;s.right_change=-1e6;s.stop=(h.planned_stop||h.force_stop)?1e5:-1e6;s.emergency_stop=h.emergency_stop?1e6:-1e6;return s;} }
